    "content": "/** 分布式运行时合同共用的基础标量。 */\ntype Ulid = string;\ntype IsoTime = string;\ntype Digest = string;\ntype KeyConfirmation = string;\ntype ProtocolVersion = string;\ntype JsonValue = null | boolean | number | string | JsonValue[] | {\n    [key: string]: JsonValue;\n};\ninterface Signature {\n    alg: string;\n    keyId: string;\n    sig: string;\n}\n/** 内容寻址对象的稳定引用；正文和真实路径不进入协议。 */\ninterface ArtifactRef {\n    digest: Digest;\n    bytes: number;\n}\n/** 所有顶层 wire 合同的当前版本标记。 */\ninterface WireContractV1 {\n    readonly v: 1;\n}\ndeclare const wireSchemaId: unique symbol;\n/** 顶层协议 schema 的编译期身份；独立于 wire 版本。 */\ninterface WireSchemaIdentity<SchemaId extends string> {\n    readonly [wireSchemaId]?: SchemaId;\n}\n/** 顶层协议 schema 的编译期身份；标记不会进入序列化结果。 */\ninterface WireSchemaV1<SchemaId extends string> extends WireContractV1, WireSchemaIdentity<SchemaId> {\n}\n\nexport type { ArtifactRef as A, Digest as D, IsoTime as I, JsonValue as J, KeyConfirmation as K, ProtocolVersion as P, Signature as S, Ulid as U, WireSchemaV1 as W, WireSchemaIdentity as a, WireContractV1 as b };\n"
